import{_ as o,l as s,o as e,c as i,v as t,p as l,x as r,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"NUMA 调度","description":"","frontmatter":{"title":"NUMA 调度","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/numa-sched.md","filePath":"cs/numa-sched.md","lastUpdated":1789023840000}'),A={name:"cs/numa-sched.md"};function m(p,a,E,u,_,f){const n=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="numa-调度" tabindex="-1">NUMA 调度 <a class="header-anchor" href="#numa-调度" aria-label="Permalink to &quot;NUMA 调度&quot;">​</a></h1><div class="epigraph"><p>任务跟着它的内存走往往比跟着闲核走更划算：远程访问的延迟可以吃掉一次「平衡」省下的排队时间。</p><footer>—— 据 Hennessy and Patterson 对 NUMA 的讨论；Love, LKD 对调度域的整理</footer></div><p><a href="/cs/cpu-affinity">上一课</a>给出 CPU 掩码。<a href="/cs/interconnect-numa">互连与 NUMA</a> 已说明本地内存快、远程慢。<a href="/cs/load-balance-migrate">负载均衡</a> 若只看队列长度，会把任务迁到「闲但内存全在另一节点」的核上。缺口是 <strong>NUMA 感知调度</strong>：负载分层（节点内先平衡），尽量在内存所在节点上跑。本课只钉这条启发，不写页迁移扫描器的全部。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一次跨节点迁任务：TLB、cache 冷，而且之后每次缺页或命中都可能走互连。一次节点内迁核：税轻得多。调度域因此是树：SMT → 核 → 节点 → 机器。缺口不是再设一个亲和位，而是<strong>平衡器比较负载时先看近层</strong>，跨节点要更高的不平衡阈值。</p><p><span class="marginnote">首次分配内存的节点常由「当前 CPU 的节点」决定。任务若在 exec 后立刻被迁走，内存会落在错误节点——home node 策略试图避免这一点。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记录任务的首选节点（home）。唤醒：优先同节点的 idle 核。周期性平衡：节点内积极，节点间保守。必要时迁页而非迁任务（或反过来），本课只承认两条路都存在，页迁移是虚存课。与 IRQ 亲和：网卡队列绑在节点上，处理线程也留在该节点。</p>',8)),(e(),l(h,null,{default:r(()=>[c(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOME%5B%22%E4%BB%BB%E5%8A%A1%20home%20%E8%8A%82%E7%82%B9%22%5D%20--%3E%20LOCAL%5B%22%E4%BC%98%E5%85%88%E6%9C%AC%E8%8A%82%E7%82%B9%20idle%22%5D%0A%20%20LOCAL%20--%3E%20FAR%5B%22%E8%B7%A8%E8%8A%82%E7%82%B9%E5%8F%AA%E5%9C%A8%E4%B8%A5%E9%87%8D%E4%B8%8D%E5%B9%B3%E8%A1%A1%E6%97%B6%22%5D%0A%20%20FAR%20--%3E%20TAX%5B%22%E8%BF%9C%E7%A8%8B%E8%AE%BF%E5%AD%98%E7%A8%8E%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>实时任务：期限优先于 NUMA 启发；但 WCET 必须按远程情况给上界，否则 RM/EDF 纸面通过、板上失败。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>NUMA 调度把<a href="/cs/scheduling-metrics">调度指标</a>里的「CPU 时间」说清楚：同样一毫秒，本地命中与远程命中做的有效工作不同。vruntime 仍按 CPU 时间记账，不按访存延迟折算——这是已知扭曲，完全公平并不等于等量工作。工程上用节点隔离来减小扭曲。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 autoNUMA、平衡页扫描的参数当正文，不讨论 GPU 显存。也不把一致性协议再导一遍。同步课即将开始：多核上共享变量的交错，不能再假设单核关中断就够。</p><p>后课默认：跑哪颗核要看内存节点。多执行流同时改共享变量时何为正确，下一课讲<a href="/cs/race-critical">竞争与临界区</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NUMA 调度：节点内先平衡，任务尽量靠近其内存。</li><li>远程闲核不一定更优；vruntime 不反映访存税。</li><li>共享变量上的竞争是下一课。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em>；Love, <em>LKD</em>。</li></ul>',8))])}const P=o(A,[["render",m]]);export{C as __pageData,P as default};
